    validationMode?: ValidationMode;
    /** Externally declared ValidatorFactory, creates internally if not provided */
    validatorFactory?: ValidatorFactory;
    /**
     * Render-level virtualization (deferred mount) for large forms (default: off)
     *  - `true`: Enable with default options
     *  - `VirtualizationOptions`: Enable with custom options
     *  - Off-screen fields render as lightweight placeholders and mount when they
     *    approach the viewport, on browser idle time, or on focus/select commands
     *  - The node tree is always fully built; values, validation and submit are unaffected
     *  - Server-rendered fields hydrate unchanged and remain revealed. Gating
     *    applies to branches and children added after hydration and requires
     *    IntersectionObserver; browsers without it mount every field eagerly.
     *  - Client-only mounts gate from the first render. Hydration itself does not
     *    trigger an extra branch render, including custom inputs with Suspense.
     */
    virtualization?: boolean | VirtualizationOptions;
    /** User-defined context */
    context?: Dictionary;
    /** Child components */
    children?: ReactNode | Fn<[
        props: FormChildrenProps<Schema, Value>
    ], ReactNode>;
}"]

["core/engine/types/state.d.ts",""<package>/dist/core/engine/types/state".FieldNodeState","/** UI state flags a node can carry. */
export declare enum FieldNodeState {
    /** Set when the user changes this node's value through its input; programmatic writes (setValue, array verbs) and automatic writes (fill, derived, injectTo, unsetValue, exit clearing, trim) never set it. Cleared by reset, controls.resetInteraction and clearState. */
    Dirty = 1,
    /** Set once the user leaves this node's input (blur) for the first time. Cleared by reset, controls.resetInteraction and clearState. */
    Touched = 2,
    /** Request validation messages for this node. Newly eligible or interrupted errors wait for the next eligibility release, with the verdict or about two frames after a quiet change; hiding is immediate. */
    ErrorVisible = 4
}"]

